{
  "title_novice": "Три части тела дельты",
  "summary": [
    {"text": "Дельта делится на три части: надводную дельтовую равнину, крутую подводную авандельту и пологую продельту.", "claims": ["c2", "c3", "c4"]},
    {"text": "Части отличаются положением относительно воды, наклоном и крупностью обломков.", "claims": ["c3", "c4"]},
    {"text": "На рис. 1.14 подписаны элементы внутри дельты; пятая подпись — продельтовая глина.", "claims": ["c5", "c6"]}
  ],
  "claims": [
    {"key": "c1", "text": "Автор переходит к перечню: дельта состоит из частей, которые он перечисляет сразу после этой фразы.", "kind": "observation", "unit_id": "u-030-1567ed", "page": 30, "quote": "высотой волн и приливных течений. Дельты состоят из:", "numbers": [], "question": null},
    {"key": "c2", "text": "Надводная часть конуса дельты называется дельтовой равниной.", "kind": "observation", "unit_id": "u-030-1067cc", "page": 30, "quote": "субаэральной части конуса дельты [subaerial delta] — дельтовой равнины,", "numbers": [], "question": null},
    {"key": "c3", "text": "Авандельта — крутая подводная часть конуса дельты из грубообломочного материала.", "kind": "observation", "unit_id": "u-030-1067cc", "page": 30, "quote": "авандельты [avandelta] — крутонаклонной подводной грубообломочной части конуса дельты;", "numbers": [], "question": null},
    {"key": "c4", "text": "Продельта — пологая часть конуса дельты из тонкого алеврито-пелитового материала.", "kind": "observation", "unit_id": "u-030-1067cc", "page": 30, "quote": "продельты [prodelta] — пологой тонкообломочной (алеврито-пелитовой) части конуса дельты (Рис. 1.14).", "numbers": ["1.14"], "question": null},
    {"key": "c5", "text": "На рис. 1.14 отмечены береговые валы (1), рукав реки (2) и внутридельтовый залив (3).", "kind": "observation", "unit_id": "u-031-727a1b", "page": 31, "quote": "1 — береговые валы; 2 — рукав реки; 3 — внутридельтовый залив;", "numbers": ["1", "2", "3"], "question": null},
    {"key": "c6", "text": "На рис. 1.14 отмечены береговые бары, перерабатывающие отмершую лопасть дельты (4), и продельтовая глина (5).", "kind": "observation", "unit_id": "u-031-727a1b", "page": 31, "quote": "4 — береговые бары, трансгрессируя, перерабатывают лопасть мертвой дельты; 5 — продельтовая глина", "numbers": ["4", "5"], "question": null}
  ],
  "mechanism": [
    {"text": "Конус выноса делят на части по трём признакам: положение относительно воды, наклон и крупность обломков.", "claims": ["c2", "c3", "c4"], "hypothesis": false},
    {"text": "Надводная часть конуса — дельтовая равнина.", "claims": ["c2"], "hypothesis": false},
    {"text": "Слово «субаэральная» означает «надводная» (общий смысл термина, не из главы).", "claims": [], "hypothesis": true},
    {"text": "Авандельта лежит под водой. Она крутая и состоит из крупных обломков.", "claims": ["c3"], "hypothesis": false},
    {"text": "Продельта — пологая часть из тонкого алеврито-пелитового материала.", "claims": ["c4"], "hypothesis": false},
    {"text": "Крупные обломки оседают быстрее и дают крутую часть, мелкие уходят дальше и дают пологую. Это объяснение не из главы.", "claims": [], "hypothesis": true},
    {"text": "На рис. 1.14 продельту подписали как продельтовую глину, то есть как тонкий глинистый осадок.", "claims": ["c6"], "hypothesis": false},
    {"text": "Внутри дельты на рис. 1.14 показаны элементы: береговые валы, рукав реки, внутридельтовый залив, береговые бары и отмершая лопасть.", "claims": ["c5", "c6"], "hypothesis": false}
  ],
  "practice": [
    {"text": "По описанию пласта определяют, над водой он лежит или под водой. Над водой — дельтовая равнина.", "claims": ["c2"], "hypothesis": true},
    {"text": "Крутой подводный грубый интервал относят к авандельте, пологий тонкий — к продельте.", "claims": ["c3", "c4"], "hypothesis": true},
    {"text": "Подписи рис. 1.14 (валы, рукав, залив, бары, лопасть) помогают узнать похожие обстановки на других схемах.", "claims": ["c5", "c6"], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Части описаны качественно: крутой или пологий, крупный или тонкий материал. Числовых порогов в тексте нет.", "claims": ["c3", "c4"], "hypothesis": false},
    {"text": "Авандельта — подводная, дельтовая равнина — надводная. Граница между ними в этом узле не разбирается.", "claims": ["c2", "c3"], "hypothesis": false},
    {"text": "Цифры 1–4 на рис. 1.14 обозначают элементы внутри дельты. Цифра 5 отмечает продельтовую глину, осадок одной из трёх частей.", "claims": ["c5", "c6", "c4"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Алеврит и пелит", "text": "Алеврит — частица мельче песка. Пелит — самая мелкая фракция, мельче алеврита. Это общее знание, не из главы.", "claims": [], "hypothesis": true},
    {"title": "Береговой вал", "text": "Береговой вал — гряда осадка вдоль берега или русла. В книге указан только номер 1 на рис. 1.14. Определение общее, не из главы.", "claims": ["c5"], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "На подписи рис. 1.14 позиции пронумерованы от 1 до 5.", "claims": ["c5", "c6"]},
    {"text": "Дельтовая равнина: надводная (субаэральная) часть конуса дельты.", "claims": ["c2"]},
    {"text": "Авандельта: крутонаклонная, подводная, грубообломочная часть конуса.", "claims": ["c3"]},
    {"text": "Продельта: пологая, тонкообломочная (алеврито-пелитовая) часть конуса.", "claims": ["c4"]}
  ],
  "terms_defined": [
    {"term": "дельтовая равнина", "term_en": "subaerial delta", "abbr": "", "definition": "Надводная (субаэральная) часть конуса дельты.", "claims": ["c2"]},
    {"term": "авандельта", "term_en": "avandelta", "abbr": "", "definition": "Крутая подводная грубообломочная часть конуса дельты.", "claims": ["c3"]},
    {"term": "продельта", "term_en": "prodelta", "abbr": "", "definition": "Пологая тонкообломочная (алеврито-пелитовая) часть конуса дельты. На рис. 1.14 она подписана как продельтовая глина.", "claims": ["c4", "c6"]},
    {"term": "дельтовый рукав", "term_en": "", "abbr": "", "definition": "Рукав реки внутри дельты. На рис. 1.14 отмечен номером 2.", "claims": ["c5"]},
    {"term": "внутридельтовый залив", "term_en": "", "abbr": "", "definition": "Залив внутри дельты. На рис. 1.14 отмечен номером 3.", "claims": ["c5"]},
    {"term": "береговой вал", "term_en": "", "abbr": "", "definition": "Элемент дельты, на рис. 1.14 отмечен номером 1.", "claims": ["c5"]},
    {"term": "лопасть дельты", "term_en": "", "abbr": "", "definition": "Отмершая часть дельты. Береговые бары при наступлении моря перерабатывают её (рис. 1.14, номер 4). Термин «трансгрессия» разбирается в n05.", "claims": ["c6"]},
    {"term": "алеврит", "term_en": "", "abbr": "", "definition": "Частица мельче песка и крупнее пелита. Общее знание, не из главы.", "claims": []},
    {"term": "пелит", "term_en": "", "abbr": "", "definition": "Самая мелкая фракция (тонкий ил), мельче алеврита. Общее знание, не из главы.", "claims": []}
  ],
